referenceSolutions.javascript:
export function threeSumClosest(values          , target        )         {
const a=[...values].sort((x,y)=>x-y);let best=a[0]+a[1]+a[2];for(let i=0;i<a.length-2;i++){let l=i+1,r=a.length-1;while(l<r){const sum=a[i]+a[l]+a[r];if(Math.abs(sum-target)<Math.abs(best-target)||(Math.abs(sum-target)===Math.abs(best-target)&&sum<best))best=sum;if(sum<target)l++;else r--;}}return best;
}

